  ACCOUNT_NAME_MAX: 100,
  STRATEGY_NAME_MAX: 100,
  STRATEGY_TEXT_MAX: 50000,
  SETUP_SYMBOL_MAX: 20,
  SETUP_NOTE_MAX: 50000,
  CUSTOM_FIELD_NAME_MAX: 50,
  WATCHLIST_SYMBOL_MAX: 30,
  REVIEW_LABEL_MAX: 100,
  REVIEW_NOTES_MAX: 100000,
  PROP_FIRM_NAME_MAX: 100,
  SETTING_KEY_MAX: 100,
  SETTING_VALUE_MAX: 100000,
  TRADE_SYMBOL_MAX: 20,
  TRADE_TEXT_MAX: 50000,
  LOGIN_RATE_LIMIT: 10,
  LOGIN_RATE_WINDOW_MS: 5 * 60 * 1000,
  SESSION_TTL: 86400 * 30,
  TRADE_LOCK_MS: 48 * 3600 * 1000,
  FX_CACHE_TTL: 3600,
  FX_CACHE_MAX_AGE_MS: 60 * 60 * 1000,
  CALENDAR_CACHE_TTL: 900,
  REORDER_MAX: 200,
  TRADES_DEFAULT_LIMIT: 500,
  TRADES_MAX_LIMIT: 5000,
