async function getFxRatesAPI(env, accountId, url) {
  const symbolsParam = url.searchParams.get('symbols');
  const symbols = symbolsParam
    ? symbolsParam.split(',').map(s => s.trim().toUpperCase()).filter(Boolean).slice(0, 50)
    : DEFAULT_FX_SYMBOLS;
  const force = url.searchParams.get('force') === '1';

  const cacheKey = 'fx_rates:' + accountId;
  if (!force && env.SESSIONS) {
    try {
      const cached = await env.SESSIONS.get(cacheKey, 'json');
      if (cached && cached.fetchedAt && (Date.now() - cached.fetchedAt < CONFIG.FX_CACHE_MAX_AGE_MS)) {
        try { await env.SESSIONS.put(cacheKey, JSON.stringify(cached), { expirationTtl: CONFIG.FX_CACHE_TTL }); } catch (_) {}
        return json({ rates: cached.rates, fetchedAt: cached.fetchedAt, source: cached.source || 'twelvedata', cached: true });
      }
    } catch (_) {}
  }

  const row = await env.DB.prepare('SELECT value FROM user_settings WHERE account_id = ? AND key = ?').bind(accountId, 'twelvedata_apikey').first();
  const apiKey = row && row.value ? String(row.value).trim() : '';
  if (!apiKey) {
    return json({ error: 'TwelveData API key not set. Open Settings -> FX Rates & Currency to add one.', rates: {}, fetchedAt: 0, source: 'none' }, 200);
  }

  const results = await Promise.all(symbols.map(async sym => {
    try {
      const r = await fetch('https://api.twelvedata.com/price?symbol=' + encodeURIComponent(sym) + '&apikey=' + encodeURIComponent(apiKey), {
        headers: { 'Accept': 'application/json' }
      });
      if (!r.ok) return { symbol: sym, error: 'HTTP ' + r.status };
      const j = await r.json();
      if (j && j.status === 'error') return { symbol: sym, error: j.message || 'API error' };
      const price = parseFloat(j && j.price);
      if (!Number.isFinite(price)) return { symbol: sym, error: 'No price in response' };
      return { symbol: sym, price };
    } catch (e) {
      return { symbol: sym, error: 'Fetch failed' };
    }
  }));

  const rates = {};
  const errors = {};
  results.forEach(r => {
    if (r.price !== undefined) rates[r.symbol] = r.price;
    else errors[r.symbol] = r.error;
  });

  const payload = { rates, errors, fetchedAt: Date.now(), source: 'twelvedata', cached: false };

  if (env.SESSIONS && Object.keys(rates).length > 0) {
    try { await env.SESSIONS.put(cacheKey, JSON.stringify(payload), { expirationTtl: CONFIG.FX_CACHE_TTL }); } catch (_) {}
  }

  return json(payload);
}

async function backupAll(env) {
  const accounts = (await env.DB.prepare('SELECT id, name, created FROM accounts ORDER BY id').all()).results;
  const accIds = accounts.map(a => a.id);
  const data = { accounts, trades: {}, strategies: {}, setups: {}, custom_fields: {}, watchlist: {}, review_notes: {}, prop_firms: {}, user_settings: {} };

  await Promise.all(accIds.map(async (accId) => {
    const [trades, strategies, setups, customFields, watchlist, reviewNotes, propFirms, userSettings] = await Promise.all([
      env.DB.prepare('SELECT * FROM trades WHERE account_id = ?').bind(accId).all(),
      env.DB.prepare('SELECT * FROM strategies WHERE account_id = ?').bind(accId).all(),
      env.DB.prepare('SELECT * FROM setups WHERE account_id = ?').bind(accId).all(),
      env.DB.prepare('SELECT name FROM custom_fields WHERE account_id = ?').bind(accId).all(),
      env.DB.prepare('SELECT symbol FROM watchlist WHERE account_id = ? ORDER BY sort_order, id').bind(accId).all(),
      env.DB.prepare('SELECT label, notes FROM review_notes WHERE account_id = ?').bind(accId).all(),
      env.DB.prepare('SELECT * FROM prop_firms WHERE account_id = ?').bind(accId).all(),
      env.DB.prepare('SELECT key, value FROM user_settings WHERE account_id = ?').bind(accId).all(),
    ]);
    data.trades[accId] = trades.results.map(parseTrade);
    data.strategies[accId] = strategies.results;
    data.setups[accId] = setups.results;
    data.custom_fields[accId] = customFields.results.map(r => r.name);
    data.watchlist[accId] = watchlist.results.map(r => r.symbol);
    data.review_notes[accId] = reviewNotes.results;
    data.prop_firms[accId] = propFirms.results.map(parsePropFirm);
    const us = {};
    userSettings.results.forEach(r => { us[r.key] = r.value; });
    data.user_settings[accId] = us;
  }));

  return json({ version: 3, type: 'trading-dashboard-cloud-backup', created: new Date().toISOString(), data });
}

async function restoreAllBackend(request, env) {
  try {
    const backup = await request.json();
    if (!backup || !backup.data || !Array.isArray(backup.data.accounts) || backup.data.accounts.length === 0) {
      return json({ error: 'Invalid backup format — expected non-empty data.accounts array' }, 400);
    }
    const d = backup.data;

    const wipeStmts = [
      'DELETE FROM trades',
      'DELETE FROM strategies',
      'DELETE FROM setups',
      'DELETE FROM custom_fields',
      'DELETE FROM watchlist',
      'DELETE FROM review_notes',
      'DELETE FROM prop_firms',
      'DELETE FROM user_settings',
      'DELETE FROM accounts',
    ];

    const insertStmts = [];

    for (const acc of d.accounts) {
      const accId = (typeof acc.id === 'number' && acc.id > 0) ? acc.id : null;
      if (accId === null) continue;
      insertStmts.push(env.DB.prepare('INSERT INTO accounts (id, name, created) VALUES (?, ?, ?)')
        .bind(accId, String(acc.name || 'Account').slice(0, CONFIG.ACCOUNT_NAME_MAX), acc.created || Date.now()));

      const trades = (d.trades && d.trades[accId]) || [];
      for (const t of trades) {
        insertStmts.push(env.DB.prepare(
          'INSERT INTO trades (id, account_id, symbol, direction, setup, entry, exit, sl, tp, size, pnl, r_multiple, status, mae, mfe, mtf4h, notes, lessons, emotion, entry_pic, rating, tags, custom, session, propfirm_id, tp1, tp2, tp3, tp1_hit, tp2_hit, tp3_hit, timestamp, date, time, fx_rate_used) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)'
        ).bind(
          (typeof t.id === 'number' && t.id > 0) ? t.id : null, accId, String(t.symbol || '').slice(0, CONFIG.TRADE_SYMBOL_MAX), t.direction || 'long', String(t.setup || '').slice(0, CONFIG.TRADE_TEXT_MAX),
          num(t.entry), num(t.exit), num(t.sl), num(t.tp), num(t.size),
          num(t.pnl), num(t.rMultiple), t.status || 'open', num(t.mae), num(t.mfe),
          String(t.mtf4h || '').slice(0, CONFIG.TRADE_TEXT_MAX),
          String(t.notes || '').slice(0, CONFIG.TRADE_TEXT_MAX), String(t.lessons || '').slice(0, CONFIG.TRADE_TEXT_MAX), String(t.emotion || '').slice(0, 100), String(t.entryPic || '').slice(0, CONFIG.TRADE_TEXT_MAX),
          parseInt(t.rating, 10) || 0,
          JSON.stringify(t.tags || []), JSON.stringify(t.custom || {}), t.session || 'london',
          String(t.propfirmId || '').slice(0, 50), num(t.tp1), num(t.tp2), num(t.tp3),
          t.tp1Hit ? 1 : 0, t.tp2Hit ? 1 : 0, t.tp3Hit ? 1 : 0,
          t.timestamp || Date.now(), t.date || '', t.time || '',
          num(t.fxRateUsed)
        ));
      }

      const strategies = (d.strategies && d.strategies[accId]) || [];
      for (const s of strategies) {
        insertStmts.push(env.DB.prepare('INSERT INTO strategies (id, account_id, name, checklist, notes, video, created) VALUES (?, ?, ?, ?, ?, ?, ?)')
          .bind((typeof s.id === 'number' && s.id > 0) ? s.id : null, accId, String(s.name || '').slice(0, CONFIG.STRATEGY_NAME_MAX), String(s.checklist || '').slice(0, CONFIG.STRATEGY_TEXT_MAX), String(s.notes || '').slice(0, CONFIG.STRATEGY_TEXT_MAX), String(s.video || '').slice(0, 2000), s.created || Date.now()));
      }

      const setups = (d.setups && d.setups[accId]) || [];
      for (const su of setups) {
        insertStmts.push(env.DB.prepare('INSERT INTO setups (id, account_id, symbol, note, pic_url, tag, timestamp, date) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
          .bind((typeof su.id === 'number' && su.id > 0) ? su.id : null, accId, String(su.symbol || '').slice(0, CONFIG.SETUP_SYMBOL_MAX), String(su.note || '').slice(0, CONFIG.SETUP_NOTE_MAX), String(su.picUrl || su.pic_url || '').slice(0, 2000), String(su.tag || 'long').slice(0, 50), su.timestamp || Date.now(), su.date || ''));
      }

      const cf = (d.custom_fields && d.custom_fields[accId]) || [];
      for (const name of cf) {
        insertStmts.push(env.DB.prepare('INSERT OR IGNORE INTO custom_fields (account_id, name) VALUES (?, ?)')
          .bind(accId, String(name).slice(0, CONFIG.CUSTOM_FIELD_NAME_MAX)));
      }

      const wl = (d.watchlist && d.watchlist[accId]) || [];
      let wlOrder = 0;
      for (const sym of wl) {
        insertStmts.push(env.DB.prepare('INSERT OR IGNORE INTO watchlist (account_id, symbol, sort_order) VALUES (?, ?, ?)')
          .bind(accId, sanitizeWatchlistSymbol(sym), wlOrder++));
      }

      const rn = (d.review_notes && d.review_notes[accId]) || {};
      if (Array.isArray(rn)) {
        for (const r of rn) {
          insertStmts.push(env.DB.prepare('INSERT INTO review_notes (account_id, label, notes, updated) VALUES (?, ?, ?, ?) ON CONFLICT(account_id, label) DO UPDATE SET notes = ?, updated = ?')
            .bind(accId, String(r.label || '').slice(0, CONFIG.REVIEW_LABEL_MAX), String(r.notes || '').slice(0, CONFIG.REVIEW_NOTES_MAX), Date.now(), String(r.notes || '').slice(0, CONFIG.REVIEW_NOTES_MAX), Date.now()));
        }
      } else {
        for (const [label, notes] of Object.entries(rn)) {
          insertStmts.push(env.DB.prepare('INSERT INTO review_notes (account_id, label, notes, updated) VALUES (?, ?, ?, ?) ON CONFLICT(account_id, label) DO UPDATE SET notes = ?, updated = ?')
            .bind(accId, String(label).slice(0, CONFIG.REVIEW_LABEL_MAX), String(notes || '').slice(0, CONFIG.REVIEW_NOTES_MAX), Date.now(), String(notes || '').slice(0, CONFIG.REVIEW_NOTES_MAX), Date.now()));
        }
      }

      const pfs = (d.prop_firms && d.prop_firms[accId]) || [];
      for (const pf of pfs) {
        insertStmts.push(env.DB.prepare(
          'INSERT INTO prop_firms (id, account_id, name, type, balance, target, target2, max_daily, max_overall, time_limit, start_date, current_step, step1_passed, step1_pnl) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)'
        ).bind(
          (typeof pf.id === 'number' && pf.id > 0) ? pf.id : null, accId, String(pf.name || '').slice(0, CONFIG.PROP_FIRM_NAME_MAX), String(pf.type || '1step').slice(0, 20),
          num(pf.balance), num(pf.target), num(pf.target2),
          num(pf.maxDaily), num(pf.maxOverall), num(pf.timeLimit),
          pf.startDate || Date.now(), pf.currentStep || 1, pf.step1Passed ? 1 : 0, num(pf.step1Pnl)
        ));
      }

      const us = (d.user_settings && d.user_settings[accId]) || {};
      for (const [key, value] of Object.entries(us)) {
        insertStmts.push(env.DB.prepare('INSERT INTO user_settings (account_id, key, value) VALUES (?, ?, ?) ON CONFLICT(account_id, key) DO UPDATE SET value = ?')
          .bind(accId, String(key).slice(0, CONFIG.SETTING_KEY_MAX), String(value ?? '').slice(0, CONFIG.SETTING_VALUE_MAX), String(value ?? '').slice(0, CONFIG.SETTING_VALUE_MAX)));
      }
    }

    await env.DB.batch([...wipeStmts.map(s => env.DB.prepare(s)), ...insertStmts]);

    return json({ success: true, accounts_restored: d.accounts.length, trades_restored: (d.trades ? Object.values(d.trades).reduce((s, ts) => s + (Array.isArray(ts) ? ts.length : 0), 0) : 0) });
  } catch (e) {
    return json({ error: 'Restore failed' }, 500);
  }
}

async function dangerWipe(request, env, accountId) {
  try {
    const body = await request.json().catch(() => ({}));
    const targets = body && Array.isArray(body.targets) ? body.targets : [];
    if (targets.length === 0) return json({ error: 'targets array required (e.g. ["trades","strategies","prop_firms"])' }, 400);

    const validTargets = new Set(['trades', 'strategies', 'prop_firms', 'setups', 'watchlist', 'review_notes', 'custom_fields']);
    const invalid = targets.filter(t => !validTargets.has(t));
    if (invalid.length > 0) return json({ error: 'Invalid targets: ' + invalid.join(', ') }, 400);

    const requiresConfirm = body.confirm !== true;
    if (requiresConfirm) return json({ error: 'Confirmation required. Set { confirm: true } to proceed.', targets }, 400);

    const stmts = targets.map(t => env.DB.prepare(`DELETE FROM ${t} WHERE account_id = ?`).bind(accountId));
    await env.DB.batch(stmts);
    return json({ success: true, wiped: targets, accountId });
  } catch (e) {
    return json({ error: 'Wipe failed' }, 500);
  }
}

function json(data, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json', ...extraHeaders } });
}
